INSERT INTO `posts` VALUES ('2', '1', 'Giỏ hàng', null, '<p><strong>Lưu ý:</strong> Quý khách có thể chọn thanh toán khi nhận hàng (COD) hoặc thanh toán qua chuyển khoản vào một trong số các tài khoản của chúng tôi.</p><p>Sau khi chuyển khoản, quý khách vui lòng chụp lại màn hình thanh toán và gửi tin nhắn cho chúng tôi vào Zalo hoặc Facebook. Chúng tôi sẽ gửi sản phẩm ngay khi xác nhận thanh toán thành công.</p><p>Xin cảm ơn quý khách đã đặt hàng!</p>', null, null, null, null, null, null, null, 'giohang', null, null, null, '9999', null, null, null, null, '9999.00', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '4.50', '1', '2024-11-22 10:05:20', null, null);
INSERT INTO `posts` VALUES ('3', '1', 'Gửi thông tin thành công', null, '<p style=\"text-align:center\">Quý khách đã gửi thông tin thành công.<br>Chúng tôi sẽ liên hệ trong thời gian sớm nhất!<br><i>You have successfully sent information. We will contact you as soon as possible!</i></p>', null, null, null, null, null, null, null, 'thanhcong', null, null, null, '9999', null, null, null, null, '9999.00', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '4.50', '1', '2024-11-22 10:05:20', null, null);
INSERT INTO `posts` VALUES ('4', '1', 'Giới thiệu', 'Chào mừng bạn đến với Kyutou, điểm đến lý tưởng cho những tín đồ yêu thích hàng Nhật Bản! ...', '<p><strong>Chào mừng bạn đến với Kyutou, điểm đến lý tưởng cho những tín đồ yêu thích hàng Nhật Bản! Chúng tôi chuyên cung cấp dịch vụ order các sản phẩm chất lượng cao từ Nhật Bản, mang đến cho bạn trải nghiệm mua sắm trực tuyến tiện lợi và an toàn.</strong></p>\n<h4>Đặc Điểm Nổi Bật của Kyutou:</h4>\n<ul>\n<li>\n<p><strong>Sản Phẩm Đa Dạng</strong>: Tại Kyutou, bạn có thể tìm thấy nhiều loại sản phẩm từ thời trang, mỹ phẩm, đồ gia dụng đến đồ công nghệ, tất cả đều được nhập khẩu chính hãng từ Nhật Bản.</p>\n</li>\n<li>\n<p><strong>Giá Cả Cạnh Tranh</strong>: Chúng tôi cam kết mang đến giá cả hợp lý nhất cho khách hàng, giúp bạn tiết kiệm chi phí mua sắm mà vẫn đảm bảo chất lượng sản phẩm.</p>\n</li>\n<li>\n<p><strong>Dịch Vụ Khách Hàng Tận Tâm</strong>: Đội ngũ nhân viên của chúng tôi luôn sẵn sàng hỗ trợ bạn trong mọi khâu từ tìm kiếm sản phẩm, đặt hàng cho đến giao hàng, đảm bảo bạn có trải nghiệm tốt nhất.</p>\n</li>\n<li>\n<p><strong>Giao Hàng Nhanh Chóng</strong>: Chúng tôi cam kết giao hàng nhanh chóng và an toàn, giúp bạn nhận được sản phẩm yêu thích trong thời gian ngắn nhất.</p>\n</li>\n<li>\n<p><strong>Chính Sách Đổi Trả Linh Hoạt</strong>: Nếu sản phẩm không đúng như mô tả hoặc gặp phải vấn đề, bạn có thể dễ dàng đổi trả theo chính sách của chúng tôi.</p>\n</li>\n</ul>\n<p><img src=\"/public/upload/banner2.jpg?1737101796346\" alt=\"banner2\" /></p>\n<h4>Tại Sao Chọn Kyutou?</h4>\n<p>Kyutou không chỉ đơn thuần là một trang web bán hàng, mà còn là cầu nối giữa bạn và thế giới sản phẩm chất lượng từ Nhật Bản. Với sự tận tâm và chuyên nghiệp, chúng tôi luôn nỗ lực mang đến sự hài lòng tối đa cho khách hàng.</p>\n<p>Hãy truy cập Kyutou ngay hôm nay để khám phá những sản phẩm độc đáo và chất lượng từ Nhật Bản!</p>', null, null, '/public/upload/noimage.jpg', null, '/public/thumbs/noimage.jpg', '', '', '', '', '', null, '9999', null, '', '', null, '9999.00', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '', '', '', '', '', '', '0', '', '4.50', '1', '2024-11-22 00:00:00', '2025-01-18 21:17:29', '2025-01-18 21:17:29');
