INSERT INTO `posts` VALUES ('42', '19,21', 'WAKODO- Nước ion điện giải 3 tháng hộp 10 gói', '<p>\r\n\r\n</p><ul><li>Giúp hấp thụ và làm sạch chất bẩn hiệu quả</li><li>Làm sạch nhanh chóng, không cần lau lại nhiều lần</li><li>Dọn dẹp dễ dàng</li><li>Chứa chiết xuất cây phỉ giúp làm dịu và cân bằng độ ẩm cho da bé</li><li>Tính axit yếu, không cồn, không hương liệu</li></ul><p></p>', '<div class=\"section-title text-blue\">Thông tin sản phẩm</div>\n<div class=\"article-content show-hide-content\">\n<div><strong>TÊN SP</strong><span> </span>: KAO- Khăn giấy ướt cho bé Merries (Gói 64 tờ)\n<p> </p>\n<p><strong>THÀNH PHẦN</strong><span> </span>: Nước, DPG, canxi clorua, BG, laureth-9, axit benzoic, natri benzoat, chiết xuất lá cây phỉ.</p>\n<p><strong>KÍCH THƯỚC (1 tờ)</strong><span> </span>: 140mm x 200mm</p>\n<p><strong>HDSD</strong><span> </span>: Mở miếng dán niêm phong trên miệng túi, kéo tấm khăn ướt lên và dùng để lau tay hoặc vùng da khác trên cơ thể.</p>\n<p><strong>THÔNG TIN CẢNH BÁO</strong><span> </span>: Không sử dụng khi lau các vết trầy xước, vết thương hở, vết chàm, sưng tấy. Sản phẩm có thể tan trong nước, tuy nhiên để tránh tắc bồn cầu, chỉ nên xả 1-2 miếng giấy/ lần với khối lượng lớn nước.</p>\n<p><strong>NGÀY SX</strong><span> </span>: Xem số lô sản xuất.</p>\n<p><strong>HSD</strong><span> </span>: Sử dụng tốt trong vòng 3 năm từ NSX.</p>\n<p><strong>NSX</strong><span> </span>: Kao Co., Ltd; 1-14-10 Nihonbashi-Kayabacho, Chuo, Tokyo 103-8210, Nhật Bản.</p>\n<p><strong>XUẤT XỨ</strong><span> </span>: Nhật Bản</p>\n</div>\n</div>', '0', '0', '/public/upload/1.jpg', '[]', '/public/thumbs/1.jpg', '', '', '', '', '', null, '9999', '', '', null, null, '9999.00', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, '', '', '', '', '', '', null, '', '4.50', '1', '2025-01-16 00:00:00', '2025-01-16 15:18:37', null);
